import detected from '../assets/model-aps.json';
import type { AccessPoint } from './aps.ts';

/** Shape written by scripts/prepare-model.ts (src/assets/model-aps.json). */
interface DetectedAp {
  id: string;
  x: number;
  y: number;
  h: number;
  mount: 'wall' | 'ceiling' | null;
  normal: { x: number; y: number } | null;
  zone: string;
}

/**
 * APs placed as black devices in the SketchUp model, detected by the model
 * pipeline (body 0.20 × 0.16 × 0.03 m). Regenerated by `npm run prepare-model`.
 */
export const MODEL_ACCESS_POINTS: readonly AccessPoint[] = (detected as DetectedAp[]).map((d) => ({
  id: d.id,
  group: 'model',
  position: { x: d.x, y: d.y, h: d.h },
  model: 'TP-Link EAP773',
  zone: d.zone,
  ...(d.mount === 'wall' && d.normal
    ? { mountHint: { kind: 'wall' as const, normal: d.normal } }
    : d.mount === 'ceiling'
      ? { mountHint: { kind: 'ceiling' as const } }
      : {}),
}));
